typedef int control_id_t;

enum
{
  INVALID_CONTROL_ID = -1,
  PSX_X = 184,
  PSX_CIRCLE,
  PSX_TRIANGLE,
  PSX_SQUARE
};

#define MAX_CHEAT_SIZE 16
#define CHEAT_SPEED 1

template<class T>
inline const T& min(const T& a, const T& b)
{
  return b < a ? b : a;
}

extern "C" void nglPrintf(const char *, ...);
asm(".equ nglPrintf__FPCce,0x003AC050");

class GraphicalMenuSystem
{
  char pad[300];
  float cheat_timer;
  int cheat_release;
  int cheat_index;
  control_id_t cheat_buffer[MAX_CHEAT_SIZE];

public:
  bool get_one_button_down(control_id_t&) const;
  void check_for_cheats(float);
};

void GraphicalMenuSystem::check_for_cheats (float time_inc)
{
  control_id_t btn;
  int i, j;

  struct
  {
    int size;
    control_id_t buttons[MAX_CHEAT_SIZE];
  }
  cheats[] =
  {
    { 4, { PSX_X, PSX_CIRCLE, PSX_TRIANGLE, PSX_SQUARE } },
    { 4, { PSX_SQUARE, PSX_TRIANGLE, PSX_CIRCLE, PSX_X } }
  };
  const int num_cheats = sizeof (cheats) / sizeof (cheats[0]);

  if (get_one_button_down (btn))
  {
    if (btn == INVALID_CONTROL_ID)
    {
      if (cheat_release)
      {
        cheat_timer = 0;
        cheat_release = false;
      }
      else
      {
        cheat_timer += time_inc;

        if (cheat_timer > CHEAT_SPEED)
          cheat_index = 0;
      }
    }
    else
    {
      if (!cheat_release)
      {
        cheat_timer = 0;
        cheat_release = true;

        cheat_buffer[cheat_index] = btn;
        cheat_index++;
      }
      else
      {
        cheat_timer += time_inc;

        if (cheat_timer > CHEAT_SPEED)
          cheat_index = 0;
      }
    }
  }
  else
  {
    cheat_timer += time_inc;

    if (cheat_timer > CHEAT_SPEED)
      cheat_index = 0;
  }

  for (;;)
  {
    bool valid = false;

    for (i = 0; i < num_cheats; i++)
    {
      int count = min (cheats[i].size, cheat_index);

      for (j = 0; j < count; j++)
      {
        if (cheats[i].buttons[j] == cheat_buffer[j])
        {
          if (j == cheat_index - 1)
            valid = true;
        }
        else
          break;
      }

      if (j == cheats[i].size)
      {
        nglPrintf ("You suck and need to cheat ? Because of that the game is now much harder !\n");
        cheat_index = 0;
        break;
      }
    }

    if (valid || cheat_index == 0)
      break;

    if (cheat_index < 0 || cheat_index >= MAX_CHEAT_SIZE)
    {
      cheat_index = 0;
      break;
    }

    for (i = 0; i < MAX_CHEAT_SIZE - 1; i++)
      cheat_buffer[i] = cheat_buffer[i+1];
    cheat_index--;
  }
}
